export default function (input) {
  const now = new Date(input.now);
  const lagos = new Date((isNaN(now.getTime()) ? new Date() : now).getTime() + 3600 * 1000);
  return { date: lagos.toISOString().slice(0, 10) };
}

export default function (input) {
  const rows = [];
  const naira = function (kobo) { const n = Number(kobo); return isFinite(n) ? Math.round(n) / 100 : 0; };
  for (const r of input.records || []) {
    if (!r) continue;
    const method = String(r.pay_method || '').toLowerCase();
    const kinds = { bankcard: 'card purchase', balancepayment: 'OPay wallet payment', banktransfer: 'transfer to terminal', bankaccount: 'transfer to terminal' };
    const when = new Date(r.completed_time || r.transaction_time || input.now);
    const t = isNaN(when.getTime()) ? new Date(input.now) : when;
    const lagos = new Date(t.getTime() + 3600 * 1000);
    const row = {
      reference: String(r.pay_no || r.order_no || ''), terminal: String(r.terminal_serial || input.terminal || ''),
      kind: kinds[method] || (method ? method.replace(/_/g, ' ') : 'pos payment'), status: String(r.status || 'success').toLowerCase(),
      approved: String(r.status || 'SUCCESS').toUpperCase() === 'SUCCESS', amount: naira(r.amount), fee: naira(r.fee || 0),
      happened_at: t.toISOString(), sale_date: lagos.toISOString().slice(0, 10), customer: String(r.sender_name || ''),
      narration: String(r.remark || ''), response: String(r.error_message || ''), event: 'opay:' + String(r.pay_type || 'pos').toLowerCase() };
    if (r.settlement_amount !== undefined && r.settlement_amount !== null) row.settled = naira(r.settlement_amount);
    if (row.reference) rows.push(row);
  }
  return { rows: rows, count: rows.length };
}
